-- ----------------------------
-- Table structure for app_alldata_system
-- ----------------------------
DROP TABLE IF EXISTS `app_alldata_system`;
CREATE TABLE `app_alldata_system`  (
  `id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `fs1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资源id',
  `infoname` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资源名称',
  `infocreateuserid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资源创建人',
  `infocreationtime` datetime NULL DEFAULT NULL COMMENT '资源创建时间',
  `fs2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资源类型',
  `fs20` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '办结状态',
  `fn1` float NULL DEFAULT NULL,
  `fn2` int(11) NULL DEFAULT NULL COMMENT '1-待审批   2-已通过   3-未通过',
  `createuserid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `creation_Time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `modification_Time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `exejbpmid` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '流程id',
  `state` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '状态值ended，activity',
  `nextnodename` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '下一节点名称',
  `nextassign` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '下一节点人员',
  `flowid_` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '流程key',
  `appid` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '自定义id',
  `nodeid_` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT ' 节点id',
  `jbpminstnce` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '流程id',
  `taskfk` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '数据源申请流程所需信息',
  `applicationreason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '申请理由',
  `applicationfile` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '申请文件路径',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

