DROP TABLE IF EXISTS `jbpm4_hist_detail`;
CREATE TABLE `jbpm4_hist_detail`  (
  `DBID_` bigint(20) NULL DEFAULT NULL,
  `CLASS_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `DBVERSION_` int(11) NULL DEFAULT NULL,
  `USERID_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `TIME_` datetime NULL DEFAULT NULL,
  `HPROCI_` bigint(20) NULL DEFAULT NULL,
  `HPROCIIDX_` int(11) NULL DEFAULT NULL,
  `HACTI_` bigint(20) NULL DEFAULT NULL,
  `HACTIIDX_` int(11) NULL DEFAULT NULL,
  `HTASK_` bigint(20) NULL DEFAULT NULL,
  `HTASKIDX_` int(11) NULL DEFAULT NULL,
  `HVAR_` bigint(20) NULL DEFAULT NULL,
  `HVARIDX_` int(11) NULL DEFAULT NULL,
  `MESSAGE_` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `OLD_STR_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `NEW_STR_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `OLD_INT_` int(11) NULL DEFAULT NULL,
  `NEW_INT_` int(11) NULL DEFAULT NULL,
  `OLD_TIME_` datetime NULL DEFAULT NULL,
  `NEW_TIME_` datetime NULL DEFAULT NULL,
  `PARENT_` bigint(20) NULL DEFAULT NULL,
  `PARENT_IDX_` int(11) NULL DEFAULT NULL
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = ' 流程历史详细表' ROW_FORMAT = DYNAMIC;

