-- ----------------------------
-- Table structure for jbpm4_hist_task
-- ----------------------------
DROP TABLE IF EXISTS `jbpm4_hist_task`;
CREATE TABLE `jbpm4_hist_task`  (
  `DBID_` bigint(20) NULL DEFAULT NULL,
  `DBVERSION_` int(11) NULL DEFAULT NULL,
  `EXECUTION_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `OUTCOME_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `ASSIGNEE_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `PRIORITY_` int(11) NULL DEFAULT NULL,
  `STATE_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `CREATE_` datetime NULL DEFAULT NULL,
  `END_` datetime NULL DEFAULT NULL,
  `DURATION_` bigint(20) NULL DEFAULT NULL,
  `NEXTIDX_` int(11) NULL DEFAULT NULL,
  `SUPERTASK_` bigint(20) NULL DEFAULT NULL
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '流程任务实例历史表' ROW_FORMAT = DYNAMIC;

