-- ----------------------------
-- Table structure for stargis_function_apply
-- ----------------------------
DROP TABLE IF EXISTS `stargis_function_apply`;
CREATE TABLE `stargis_function_apply`  (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `resourceid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资源ID',
  `opgrant` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '2' COMMENT '权限 检索-1   查看-2',
  `optype` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'user' COMMENT '操作者类型   user-用户、org-组织',
  `opid` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作者ID',
  `creation_time` datetime NULL DEFAULT NULL,
  `modification_time` datetime NULL DEFAULT NULL,
  `enable` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '1' COMMENT '启用标志，1-启用，0-停用',
  `field` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '字段，多选',
  `region` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '区域'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '(功能查看申请表)' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of stargis_function_apply
-- ----------------------------

-- ----------------------------
-- Table structure for stargis_function_attr
-- ----------------------------
DROP TABLE IF EXISTS `stargis_function_attr`;
CREATE TABLE `stargis_function_attr`  (
  `id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `userdataurl` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '数据服务URL',
  `CREATEUSERID` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建者用户id',
  `createDepId` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人所属机构',
  `modifyUserId` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '修改人',
  `modifyDepId` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '修改人所属机构',
  `functionid` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '功能信息表id',
  `creation_Time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `modification_Time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `treenodeid` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '功能树id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '功能属性说明' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of stargis_function_attr
-- ----------------------------

-- ----------------------------
-- Table structure for stargis_function_shareinfo
-- ----------------------------
DROP TABLE IF EXISTS `stargis_function_shareinfo`;
CREATE TABLE `stargis_function_shareinfo`  (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `resourceid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资源ID',
  `opgrant` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '权限 检索-1   查看-2',
  `optype` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作者类型   user-用户、org-组织',
  `opid` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作者ID',
  `creation_time` datetime NULL DEFAULT NULL,
  `modification_time` datetime NULL DEFAULT NULL,
  `enable` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '1' COMMENT '启用标志，1-启用，0-停用',
  `field` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '字段，多选',
  `region` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '区域，可多选'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '(图层共享信息表)' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of stargis_function_shareinfo
-- ----------------------------

-- ----------------------------
-- Table structure for stargis_function_treetable
-- ----------------------------
DROP TABLE IF EXISTS `stargis_function_treetable`;
CREATE TABLE `stargis_function_treetable`  (
  `id` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '名称',
  `icon` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '图标',
  `parentid` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '父级节点',
  `apporder` float NULL DEFAULT NULL COMMENT '序号',
  `oldid` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原方案id',
  `nodetype` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '是否为节点  node，group',
  `createUserId` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `createOrgId` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人所属机构',
  `creation_Time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `modification_Time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `hasapp` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '是否有业务节点 1-有  0-无  （是否是根节点）',
  `sceneid` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '绑定场景',
  `ztreebusi` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '业务分类  暂时没用 layer',
  `myscope` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '范围 这里暂时没用到',
  `fknodetype` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '辅助处理节点类型 与myscope 结合处理',
  `description` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '描述'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin ROW_FORMAT = DYNAMIC;

